from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to cover the required section lengths with bounded sensors."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # Enumerate per-section feasible combinations and combine them while
    # respecting the shared sensor inventory.
    options = []
    for demand in sections[:n]:
        section = []
        max_a = min(k1, (demand + l1 - 1) // l1)
        for a in range(max_a + 1):
            remaining = max(0, demand - a * l1)
            b = (remaining + l2 - 1) // l2
            if b <= k2:
                section.append((a, b, a * c1 + b * c2))
        # For each usage count of type 1 only the smallest sufficient type 2
        # count was considered, which is enough since costs are nonnegative.
        options.append(section)

    # Sparse dynamic programming over the counts actually used.
    dp = {(0, 0): 0}
    for section in options:
        if not section:
            return -1
        nxt = {}
        for (used1, used2), cost in dp.items():
            for a, b, price in section:
                x, y = used1 + a, used2 + b
                if x <= k1 and y <= k2:
                    key = (x, y)
                    value = cost + price
                    if value < nxt.get(key, float("inf")):
                        nxt[key] = value
        dp = nxt
        if not dp:
            return -1
    return min(dp.values()) if dp else -1

