from math import isqrt

_MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma divisible by 3.

    For a product n with prime exponents e_p, the number of ordered sequences
    is prod_p binom(M + e_p - 1, e_p).  Since sigma is multiplicative, modulo
    3 its factor at p**e is 1 for p=3, e+1 for p=1 (mod 3), and 1 for even
    e or 0 for odd e when p=2 (mod 3).
    """
    if N < 1 or M < 1:
        return 0

    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    local_weight = [1] * (N.bit_length() + 1)
    for e in range(1, len(local_weight)):
        local_weight[e] = local_weight[e - 1] * (M + e - 1) % _MOD
        local_weight[e] = local_weight[e] * pow(e, _MOD - 2, _MOD) % _MOD

    answer = 0
    block_size = 100_000
    for lo in range(1, N + 1, block_size):
        hi = min(N + 1, lo + block_size)
        length = hi - lo
        remaining = list(range(lo, hi))
        weights = [1] * length
        divisible = bytearray(length)

        for p in primes:
            first = ((lo + p - 1) // p) * p
            for value in range(first, hi, p):
                i = value - lo
                r = remaining[i]
                e = 0
                while r % p == 0:
                    r //= p
                    e += 1
                if e:
                    remaining[i] = r
                    weights[i] = weights[i] * local_weight[e] % _MOD
                    if (p % 3 == 1 and e % 3 == 2) or (p % 3 == 2 and e % 2 == 1):
                        divisible[i] = 1

        for i, rem in enumerate(remaining):
            if rem > 1:
                weights[i] = weights[i] * local_weight[1] % _MOD
                if rem % 3 == 2:
                    divisible[i] = 1

        for i, is_divisible in enumerate(divisible):
            if is_divisible:
                answer = (answer + weights[i]) % _MOD

    return answer

