def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count integers x in [num1, num2] whose digit sum is in [min_sum, max_sum].
    The result is returned modulo 10^9 + 7.
    """
    mod = 1_000_000_007

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        loose = [0] * (limit + 1)
        exact_sum = 0
        exact = True
        for char in bound:
            digit = ord(char) - ord("0")
            next_loose = [0] * (limit + 1)
            for total, ways in enumerate(loose):
                if ways:
                    for d in range(10):
                        new_total = total + d
                        if new_total <= limit:
                            next_loose[new_total] = (next_loose[new_total] + ways) % mod
            if exact:
                for d in range(digit):
                    total = exact_sum + d
                    if total <= limit:
                        next_loose[total] = (next_loose[total] + 1) % mod
                exact_sum += digit
                if exact_sum > limit:
                    exact = False
            loose = next_loose
        return (sum(loose) + (1 if exact else 0)) % mod

    def decrement(value: str):
        digits = list(value)
        index = len(digits) - 1
        while index >= 0 and digits[index] == "0":
            digits[index] = "9"
            index -= 1
        if index < 0:
            return None
        digits[index] = str(int(digits[index]) - 1)
        return "".join(digits).lstrip("0") or "0"

    def cumulative(bound: str) -> int:
        return (count_at_most(bound, max_sum) - count_at_most(bound, min_sum - 1)) % mod

    previous = decrement(num1)
    before_range = cumulative(previous) if previous is not None else 0
    return (cumulative(num2) - before_range) % mod

